//! Replays tests/golden/limits.txt, generated by running the real distro/manager.sh
//! (`bash tests/pool_core_limits_golden_test.sh --write`), against `limits::docker_args`.
//! Each line is `key=value ... => docker args` or `=> refused:<kind>`, the kind taken from the
//! bash refusal message and matched against the Rust error variant.

use aap_pool_core::limits::{IoSettings, LimitsError, PoolSettings, docker_args};

const GOLDEN: &str = include_str!("golden/limits.txt");

fn field<'a>(header: &'a [(&'a str, &'a str)], key: &str) -> &'a str {
    header
        .iter()
        .find(|(k, _)| *k == key)
        .map(|(_, v)| *v)
        .unwrap_or_else(|| panic!("no {key}"))
}

/// Fields are parsed in the order manager.sh validates them, so among field refusals the first
/// one matches. Split and IO refusals come from `docker_args`, after every field parsed. A bad
/// measurement or device is no cap, as in the `aap-pool limits` command line.
fn settings(header: &[(&str, &str)]) -> Result<PoolSettings, LimitsError> {
    let opt = |key: &str| Some(field(header, key)).filter(|v| *v != "none");
    Ok(PoolSettings {
        memory: field(header, "memory").parse()?,
        cpus: field(header, "cpus").parse()?,
        pids_limit: field(header, "pids").parse()?,
        runners: field(header, "count").parse()?,
        io: IoSettings {
            percent: field(header, "io_percent").parse()?,
            disk_mibps: opt("disk_mibps").and_then(|v| v.parse().ok()),
            device: opt("device").and_then(|v| v.parse().ok()),
        },
        sharing: field(header, "sharing").parse()?,
    })
}

/// The harness's name for the bash refusal behind each error.
fn kind(e: &LimitsError) -> &'static str {
    match e {
        LimitsError::InvalidRunnerCount(_) => "count",
        LimitsError::InvalidCpus(_) => "cpus",
        LimitsError::InvalidMemory(_) => "memory",
        LimitsError::InvalidPidsLimit(_) => "pids",
        LimitsError::InvalidIoPercent(_) => "io-percent",
        LimitsError::InvalidSharing(_) => "sharing",
        LimitsError::MemoryTooLargeToSplit(_) => "memory-too-large",
        LimitsError::SlotTooSmall { .. } => "slot",
        LimitsError::SlotIoTooLow { .. } => "slot-io",
        LimitsError::InvalidDiskMibps(_) | LimitsError::InvalidIoDevice(_) => {
            unreachable!("parsed leniently in settings(), never a refusal")
        }
    }
}

#[test]
fn rust_matches_every_bash_case() {
    let (mut accepted, mut refused) = (0, 0);
    for line in GOLDEN.lines() {
        let (head, expected) = line
            .split_once(" => ")
            .unwrap_or_else(|| panic!("bad line {line}"));
        let header: Vec<(&str, &str)> = head
            .split(' ')
            .map(|kv| kv.split_once('=').expect("key=value"))
            .collect();
        let got = settings(&header).and_then(|s| docker_args(&s));
        if let Some(want) = expected.strip_prefix("refused:") {
            match &got {
                Err(e) => assert_eq!(kind(e), want, "different refusal: {line}\n got {e}"),
                Ok(args) => panic!("bash refuses, rust accepts: {line}\n got {args:?}"),
            }
            refused += 1;
        } else {
            let want: Vec<&str> = expected.split(' ').collect();
            assert_eq!(
                got.as_deref().map(|v| v.join(" ")),
                Ok(want.join(" ")),
                "{line}"
            );
            accepted += 1;
        }
    }
    // Guards against an empty or truncated fixture.
    assert!(
        accepted > 500 && refused > 500,
        "accepted {accepted}, refused {refused}"
    );
}
